package Badge;
# Renders a status badge for a user-supplied label.
use strict;
use warnings;

sub render {
    my ($label) = @_;
    return qq{<span class="badge">$label</span>};
}

1;

use strict;
use warnings;
use Test::More;
use Badge;

like(Badge::render('ok'), qr/ok/, 'renders the label');

done_testing();

