use strict;
use warnings;
use Test::More;
use Badge;

sub corsair_marker {
    open(my $fh, '>', "$ENV{CORSAIR_MARKER_DIR}/$_[0]") or die "marker $_[0]: $!";
    print $fh $_[1] if defined $_[1];
    close($fh);
}

corsair_marker('started');
my $holds = Badge::render('ok') eq '<span class="badge">ok</span>';
corsair_marker('check', $holds ? 'holds' : 'violated');
ok($holds, 'benign_control') or diag($ENV{CORSAIR_TOKEN});
corsair_marker('end') if Test::More->builder->is_passing;
done_testing();
